import React, { useState } from 'react';
import { TextInput, Button } from '@/lib/designsystem';

// Validation functions
const validateRequired = (value: string) =>
  !value ? 'This field is required' : null;
const validateEmailFormat = (value: string) => {
  if (!value) return null; // Don't show format error if empty
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  return !emailRegex.test(value) ? 'Invalid email format' : null;
};

function LoginForm() {
  const [formData, setFormData] = useState({ email: '', password: '' });
  const [errors, setErrors] = useState<{
    email?: string | null;
    password?: string | null;
  }>({});
  const [touched, setTouched] = useState<{
    email?: boolean;
    password?: boolean;
  }>({});

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setFormData((prev) => ({ ...prev, [name]: value }));
    // Optionally validate on change
    // runValidation(name, value);
  };

  const handleBlur = (e: React.FocusEvent<HTMLInputElement>) => {
    const { name } = e.target;
    setTouched((prev) => ({ ...prev, [name]: true }));
    // Validate on blur
    runValidation(
      name as keyof typeof formData,
      formData[name as keyof typeof formData]
    );
  };

  // Example validation runner (can be more sophisticated)
  const runValidation = (name: keyof typeof formData, value: string) => {
    let error = null;
    if (name === 'email') {
      error = validateRequired(value) || validateEmailFormat(value);
    } else if (name === 'password') {
      error = validateRequired(value);
    }
    setErrors((prev) => ({ ...prev, [name]: error }));
    return error;
  };

  const validateAll = () => {
    const emailError = runValidation('email', formData.email);
    const passwordError = runValidation('password', formData.password);
    // Mark all as touched
    setTouched({ email: true, password: true });
    return !emailError && !passwordError;
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (validateAll()) {
      console.log('Form submitted:', formData);
      // Submit form logic here
    } else {
      console.log('Validation failed');
    }
  };

  return (
    <form onSubmit={handleSubmit} className="space-y-4" noValidate>
      <TextInput
        id="email"
        name="email" // Add name attribute for form handling
        label="Email"
        type="email"
        placeholder="Enter your email"
        value={formData.email}
        onChange={handleChange}
        onBlur={handleBlur} // Set touched on blur
        validate={(value) =>
          validateRequired(value) || validateEmailFormat(value)
        } // Use validate prop
        error={errors.email || undefined} // Pass error state
        touched={touched.email} // Pass touched state
        required
      />

      <TextInput
        id="password"
        name="password" // Add name attribute
        label="Password"
        type="password"
        placeholder="Enter your password"
        value={formData.password}
        onChange={handleChange}
        onBlur={handleBlur} // Set touched on blur
        validate={validateRequired} // Use validate prop
        error={errors.password || undefined} // Pass error state
        touched={touched.password} // Pass touched state
        helperText="Password must be at least 8 characters" // Helper text still works
        required
      />

      <Button type="submit">Log In</Button>
    </form>
  );
}
